  100	  private root: Root;
  101	  private scope: Scope;
  102	  private resizeObserver: ResizeObserver;
  103	  private cleanupListeners: (() => void)[] = [];
  104	
  105	  constructor({ plugin, view, triggerFrom, trigger }: NodeSummonMenuOptions) {
  106	    this.plugin = plugin;
  107	    this.view = view;
  108	    this.triggerFrom = triggerFrom;
  109	    this.trigger = trigger;
  110	    // Loaded once per opening; typing only re-ranks.
  111	    this.nodes = new QueryEngine(plugin.app).getSearchableNodes(
  112	      plugin.settings.nodeTypes,
  113	    );
  114	
  115	    const doc = view.dom.ownerDocument;
  116	    this.containerEl = doc.body.createDiv({
  117	      cls: "suggestion-container dg-node-summon-menu",
  118	    });
  119	    // Mounted directly so .suggestion is the flex child that scrolls inside the capped container.
  120	    this.root = createRoot(this.containerEl);
  121	
  122	    // Parented to app.scope so unrelated hotkeys keep working while the menu is open.
  123	    this.scope = new Scope(plugin.app.scope);
  124	    // Returning true lets an IME composition keep its own Enter and arrow keys.
  125	    this.scope.register(
