  127	      "ArrowDown",
  128	      (evt) => evt.isComposing || this.move(1),
  129	    );
  130	    this.scope.register(
  131	      [],
  132	      "ArrowUp",
  133	      (evt) => evt.isComposing || this.move(-1),
