  224	    const link = this.plugin.app.fileManager.generateMarkdownLink(
  225	      node.file,
  226	      sourcePath ?? "",
  227	    );
  228	    const to = this.view.state.selection.main.head;
  229	    const from = this.triggerFrom;
  230	
  231	    this.close();
