  250	      <NodeSummonList
  251	        groups={this.groups}
  252	        activeIndex={this.activeIndex}
  253	        onSelect={(index) => this.select(index)}
  254	        onHover={(index) => {
  255	          if (index === this.activeIndex) return;
  256	          this.activeIndex = index;
