  266	      read: (view) => view.coordsAtPos(this.triggerFrom),
  267	      write: (coords) => {
  268	        // A trigger scrolled out of view would leave the menu over unrelated text.
  269	        const scroller = this.view.scrollDOM.getBoundingClientRect();
