  288	          ? Math.max(VIEWPORT_MARGIN, coords.top - height - 4)
  289	          : coords.bottom + 4;
  290	        this.containerEl.style.left = `${left}px`;
  291	        this.containerEl.style.top = `${top}px`;
  292	      },
  293	    });
  294	  }
