   36	  const triggerFrom = update.changes.mapPos(menu.triggerFrom);
   37	  const queryFrom = triggerFrom + menu.trigger.length;
   38	  const head = selection.main.head;
   39	
   40	  const triggerIntact =
   41	    queryFrom <= doc.length &&
   42	    doc.sliceString(triggerFrom, queryFrom) === menu.trigger;
   43	  const cursorInQuery =
   44	    selection.main.empty &&
   45	    head >= queryFrom &&
   46	    doc.lineAt(head).number === doc.lineAt(triggerFrom).number;
